class Solution {
    public:int numberOfStableArrays(int zero,int one,int limit){
        const long long mod=1000000007;
        vector<vector<int>> endZero(zero+1,vector<int>(one+1)),endOne(zero+1,vector<int>(one+1));
        for(int count=1;count<=min(zero,limit);++count)endZero[count][0]=1;
        for(int count=1;count<=min(one,limit);++count)endOne[0][count]=1;
        for(int usedZero=1;usedZero<=zero;++usedZero)for(int usedOne=1;usedOne<=one;++usedOne){
            long long ways=endZero[usedZero-1][usedOne]+endOne[usedZero-1][usedOne];
            if(usedZero>limit)ways-=endOne[usedZero-limit-1][usedOne];
            endZero[usedZero][usedOne]=(ways+mod)%mod;
            ways=endZero[usedZero][usedOne-1]+endOne[usedZero][usedOne-1];
            if(usedOne>limit)ways-=endZero[usedZero][usedOne-limit-1];
            endOne[usedZero][usedOne]=(ways+mod)%mod;
        }
        return (endZero[zero][one]+endOne[zero][one])%mod;
    }
};
